arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error'), d.get('response_metadata'))
    sys.exit(0)
for c in d['channels']:
    if 'incident' in c['name'].lower():
        print(c['id'], c['name'])
"

